{
  Calculates the factorial of a given number N modulo 10007.

  Parameters:
  - N (integer): An integer representing the input value (N <= 10000).

  Returns:
  - integer: The factorial of N modulo 10007.

  Examples:
  - process_request(1) returns 1
  - process_request(2) returns 2
  - process_request(3) returns 6
}
function process_request(n: integer): integer;

source_record.canonical_solution:
const
  MODULO = 10007;
var
  a: array[0..10000] of integer;
  i: integer;
begin
  // Initialize the first two factorials
  a[0] := 1;
  a[1] := 1;
  // Calculate factorials up to 10000 modulo 10007
  for i := 2 to 10000 do
  begin
    a[i] := (a[i-1] * i) mod MODULO;
  end;

  // Return the requested factorial modulo
  process_request := a[n];
end;

