var
  i: integer;
  numerator, denominator: Int64;
begin
  if (n + m) mod 2 = 1 then
  begin
    countPermutationsOfBinaryString := 0;
    exit;
  end
  else if n = m then
  begin
    countPermutationsOfBinaryString := 1;
    exit;
  end;

  numerator := 1;
  denominator := 1;

  for i := 1 to (n - m) div 2 do
  begin
    numerator := numerator * (n - i + 1);
    denominator := denominator * i;
    // Reduce the fraction at each step to prevent overflow
    if numerator mod denominator = 0 then
    begin
      numerator := numerator div denominator;
      denominator := 1;
    end;
  end;

  countPermutationsOfBinaryString := numerator; // This is now C(n, (n-m)/2)
end;

