var
  i, j, k, temp, edges_count, sum: integer;
begin
  edges_count := length(edges);
  // Bubble sort to sort the array of edges
  for i := 0 to edges_count - 2 do
    for j := 0 to edges_count - i - 2 do
      if edges[j] > edges[j + 1] then
      begin
        temp := edges[j];
        edges[j] := edges[j + 1];
        edges[j + 1] := temp;
      end;

  sum := 0;
  // Counting acute-angled triangles
  for i := 0 to edges_count - 3 do
    for j := i + 1 to edges_count - 2 do
      for k := j + 1 to edges_count - 1 do
        if (edges[i] < edges[j] + edges[k]) and (sqr(edges[i]) + sqr(edges[j]) > sqr(edges[k])) then
          inc(sum);

  count_acute_triangles := sum;
end;

