uses
  SysUtils;
function countBalancedSubsequences(n, m, k: int64): int64;
const
  P: int64 = 1000000007; // 10^9 + 7
var
  C: array[0..1003, 0..503] of int64;
  i, j: int64;

begin
  // Initialize binomial coefficient matrix.
  for i := 0 to n + m + 2 do
    C[i][0] := 1;
    for j := 1 to i do
      C[i][j] := 0;
  for i := 1 to n + m + 2 do
    for j := 1 to i do
      C[i][j] := (C[i - 1][j - 1] + C[i - 1][j]) mod P;
  // Return the number of balanced subsequences.
  if (k > n) or (k > m) then
  begin
    countBalancedSubsequences := 0;
    exit;
  end;

  countBalancedSubsequences := (C[n + m][k] - C[n + m][k - 1] + P) mod P;
end;

